#include <iostream>
int main() {
    int value{};
    int sum{};
    int count{};
    while (count < 10 && (std::cin >> value)) {
        if (value == 0) { break; }
        if (value < -1000 || value > 1000) { std::cout << "invalid\n"; return 0; }
        sum += value;
        ++count;
    }
    std::cout << count << ' ' << sum << '\n';
}

#include <iostream>
int main() {
    int before{};
    while (false) { ++before; }
    int after{};
    do { ++after; } while (false);
    std::cout << before << ' ' << after << '\n';
}

